/// One past the highest COMMITTED offset, `0` while the offset space is
/// still empty. The value stamped into the durable record, and what a
/// transfer offer advertises.
///
/// Not [`Self::mint_frontier`]: after a reservation-seeded boot the append
/// point stands a lease block above this, and neither the record nor an
/// offer may claim offsets no message reached.
#[must_use]
pub fn offset_frontier(&self) -> u64 {
    if self.offset_space.committed_seeded {
        self.offset.load(Ordering::Acquire).saturating_add(1)
    } else {
        0
    }
}

/// [`Self::offset_frontier`] as it stood once every op below `op` was
/// applied, read off the stamped entries this replica still holds.
///
/// `None` when an applied op from `op` up to the first one that minted
/// offsets is no longer retained, so the frontier there cannot be known.
#[must_use]
pub fn offset_frontier_before(&self, op: u64) -> Option<u64> {
    let journal = &self.log.journal().inner;
    for applied in op..=self.consensus.commit_min() {
        let entry = journal.repair_entry(applied)?;
        if let Some(batch) = materialization_batch_meta(&entry, None).ok()? {
            return Some(batch.base_offset);
        }
    }
    Some(self.offset_frontier())
}

/// The offset the next mint will take, which is where the segment chain has
/// to be anchored for the appends that follow to land contiguously.
///
/// Above [`Self::offset_frontier`] by exactly the offsets this replica has
/// journaled but not committed, plus -- on the first boot after a crash that
/// took acked-but-unflushed messages with it -- the lease block the durable
/// reservation claimed. That gap is the whole point: the reservation is the
/// only surviving witness that those offsets were handed to a client, so the
/// counter resumes above them instead of re-minting them.
#[must_use]
pub fn mint_frontier(&self) -> u64 {
    if self.offset_space.append_live {
        self.dirty_offset.load(Ordering::Relaxed).saturating_add(1)
    } else {
        0
    }
}

/// `Partition` represents the information about a partition.
/// It consists of the following fields:
/// - `id`: unique identifier of the partition.
/// - `created_at`: the timestamp of the partition creation.
/// - `segments_count`: the number of segments in the partition.
/// - `current_offset`: the current offset of the partition.
/// - `size_bytes`: the size of the partition in bytes.
/// - `messages_count`: the number of messages in the partition.
/// - `context`: the partition incarnation and the metadata operation the details were read at.
#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct Partition {
    /// Unique identifier of the partition.
    pub id: u32,
    /// The timestamp of the partition creation.
    pub created_at: IggyTimestamp,
    /// The number of segments in the partition.
    pub segments_count: u32,
    /// The current offset of the partition.
    pub current_offset: u64,
    /// The size of the partition in bytes.
    pub size: IggyByteSize,
    /// The number of messages in the partition.
    pub messages_count: u64,
    /// The partition incarnation and the metadata operation the details were read at. The
    /// owner generation is zero because the details belong to no consumer group.
    pub context: PartitionContext,
}

protected def createAuxiliaryTableIfNotExists(spark: SparkSession): TableIdentifier = {
  val auxIdent = AutoCdcAuxiliaryTable.identifier(destination.identifier)
  val (catalog, v2Identifier) = PipelinesCatalogUtils.resolveTableCatalog(spark, auxIdent)

  if (!catalog.tableExists(v2Identifier)) {
    val properties = mutable.Map.empty[String, String]

    // Inherit the target's format so MERGE semantics line up. When unspecified, omit the
    // provider so the catalog falls back to its default.
    destination.format.foreach { fmt => properties(TableCatalog.PROP_PROVIDER) = fmt }

    // Record which SCD strategy this auxiliary table serves so downstream readers can
    // identify it without having to inspect the schema.
    properties(AutoCdcAuxiliaryTable.scdTypePropertyKey) = changeArgs.storedAsScdType.label

    // Persist the AutoCDC key column names as a JSON list on first creation. The value
    // is stored verbatim by the catalog.
    properties(AutoCdcAuxiliaryTable.keyColumnNamesProperty) =
      AutoCdcAuxiliaryTable.serializeKeyColumnNames(auxiliaryKeyColumnNames)

    // Table creation is not atomic with the table exists check, and [[createTable]] will fail
    // with TableAlreadyExistsException if some asynchronous process creates the table between
    // the [[tableExists]] check and [[createTable]]. This is both rare (we don't support
    // multi-AutoCDC-flow targets so there are no race conditions within a single pipeline) and
    // acceptable - users can cleanly retry the failed flow when this happens. SQL offers an
    // atomic CREATE IF NOT EXISTS, but would require special casing of the table properties
    // in DDL and we would lose compile-time syntax and type safety.
    catalog.createTable(
      v2Identifier,
      new TableInfo.Builder()
        .withColumns(CatalogV2Util.structTypeToV2Columns(auxiliaryTableSchema))
        .withProperties(properties.asJava)
        .build()
    )
  }
